//! Separate source and decoded native Text admission for markup replacement.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>Held</noscript><button id=button><noscript id=guard>Guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://markup-output.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->String{let source=format!("var failure=null;try{{{s}}}catch(e){{failure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let Value::String(e)=p.runtime.execute("failure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()else{panic!("Expected refusal: {s}")};e}}}

#[test]
fn inner_html_output_decoded_text_limit_without_observation_preserves_native_tree(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),old=host.firstChild,source='\\0\\0';");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let count=f.controls.len();let strings=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=3;
 let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=source;");assert!(e.contains("Decoded HTML Text"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls.len(),count);p.state.limits.host.string_bytes=strings;p.begin_job();
 run(&mut d,&mut f,&mut p,"if(host.firstChild!==old||old.parentNode!==host||old.data!=='Held')throw 'no decoded prefix';host.innerHTML='Recovered&amp;';if(host.firstChild.data!=='Recovered&amp;'||old.parentNode!==null)throw 'fresh literal recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn inner_html_output_observer_iterator_and_range_preflight_refuses_same_decoded_text(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),old=host.firstChild,source='\\0\\0',watch=new MutationObserver(function(){}),r=document.createRange(),walk=document.createNodeIterator(host,4);r.setStart(old,1);r.setEnd(old,3);if(walk.nextNode()!==old)throw 'native old iterator';watch.observe(host,{childList:true,subtree:true});");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let strings=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=3;
 let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=source;");assert!(e.contains("Decoded HTML Text"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.limits.host.string_bytes=strings;p.begin_job();
 run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||host.firstChild!==old||r.startContainer!==old||r.startOffset!==1||r.endOffset!==3||walk.nextNode()!==null)throw 'native preflight refusal';host.innerHTML='Fresh';var text=host.firstChild,records=watch.takeRecords();if(text.data!=='Fresh'||text===old||old.parentNode!==null||r.startContainer!==host||r.startOffset||r.endOffset||walk.nextNode()!==text||records.length!==1||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==text)throw 'native observer iterator Range recovery';");
}
#[test]
fn inner_html_output_decoded_scalar_boundary_and_exact_unit_logical_size(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),source='\\0\\0',raw='\\udfff\\ud800';");let strings=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=6;run(&mut d,&mut f,&mut p,"host.innerHTML=source;");p.state.limits.host.string_bytes=strings;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild.data!=='\\ufffd\\ufffd')throw 'decoded exact scalar boundary';");
 p.state.limits.host.string_bytes=4;run(&mut d,&mut f,&mut p,"host.innerHTML=raw;");p.state.limits.host.string_bytes=strings;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild.data!==raw||host.firstChild.data.charCodeAt(0)!==57343||host.firstChild.data.charCodeAt(1)!==55296)throw 'authoritative unit size';");
 let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.state.limits.host.string_bytes=5;let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=source;");assert!(e.contains("Decoded HTML Text"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.limits.host.string_bytes=strings;
}
#[test]
fn inner_html_output_author_effects_and_observed_record_survive_later_resource_refusal(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),old=host.firstChild,out=document.getElementById('out'),calls=0,captured=null,watch=new MutationObserver(function(){});watch.observe(out,{childList:true});var source={toString:function(){calls++;out.textContent='X';captured=watch.takeRecords();return '\\0\\0';}};");let count=d.nodes.len();let strings=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=3;
 let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=source;");assert!(e.contains("Decoded HTML Text"),"{e}");p.state.limits.host.string_bytes=strings;p.begin_job();run(&mut d,&mut f,&mut p,"if(calls!==1||out.textContent!=='X'||host.firstChild!==old||old.data!=='Held'||captured.length!==1||captured[0].target!==out||captured[0].addedNodes[0]!==out.firstChild||watch.takeRecords().length)throw 'completed author effects retained';host.innerHTML='Fresh';if(host.firstChild.data!=='Fresh'||old.parentNode!==null)throw 'author effects recovery';");assert_eq!(d.nodes.len(),count+2);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
